<?php
use Modules\Core\Models\User;use Modules\Finance\Models\BankAccount;use Modules\Finance\Models\GlPeriod;use Modules\Finance\Services\PeriodCloseService;use Modules\MasterData\Models\ChartOfAccount;use Modules\MasterData\Models\Supplier;use Modules\Purchasing\Models\SupplierInvoice;
it('menjalankan maker checker sampai period CLOSED',function(){$maker=User::factory()->create(['company_id'=>1]);$checker=User::factory()->create(['company_id'=>1]);$svc=app(PeriodCloseService::class);$run=$svc->prepare(1,'2026-08',['backup_verified'=>true,'tax_reviewed'=>true,'notes'=>'Backup dan tax reviewed'],$maker);expect($run->status)->toBe('READY')->and($run->checklist_snapshot['journal_balance']['passed'])->toBeTrue();expect(fn()=>$svc->approve($run,$maker))->toThrow(RuntimeException::class,'harus berbeda');$approved=$svc->approve($run->fresh(),$checker);expect($approved->status)->toBe('APPROVED')->and($approved->approved_by)->toBe($checker->id);$closed=$svc->close($approved,$checker);expect($closed->status)->toBe('CLOSED')->and(GlPeriod::where('period','2026-08')->first()->status)->toBe('CLOSED');});
it('menolak approval ketika checklist menjadi stale',function(){$maker=User::factory()->create(['company_id'=>1]);$checker=User::factory()->create(['company_id'=>1]);$run=app(PeriodCloseService::class)->prepare(1,'2026-08',['backup_verified'=>true,'tax_reviewed'=>true],$maker);$supplier=Supplier::create(['company_id'=>1,'code'=>'S-'.uniqid(),'name'=>'Pending Vendor','type'=>'FABRIC']);SupplierInvoice::create(['company_id'=>1,'doc_no'=>'AP-'.uniqid(),'supplier_id'=>$supplier->id,'invoice_date'=>'2026-08-31','total_amount'=>100,'status'=>'DRAFT','match_status'=>'PENDING','created_by'=>$maker->id]);app(PeriodCloseService::class)->approve($run,$checker);})->throws(RuntimeException::class,'prepare ulang');
it('bank account aktif wajib mempunyai statement yang sudah reconciled',function(){$maker=User::factory()->create(['company_id'=>1]);$coa=ChartOfAccount::create(['company_id'=>1,'code'=>'BANK-'.uniqid(),'name'=>'Bank','type'=>'ASSET','normal_balance'=>'DEBIT']);BankAccount::create(['company_id'=>1,'code'=>'B-'.uniqid(),'name'=>'Bank','bank_name'=>'Bank','coa_id'=>$coa->id,'is_active'=>true]);$run=app(PeriodCloseService::class)->prepare(1,'2026-08',['backup_verified'=>true,'tax_reviewed'=>true],$maker);expect($run->status)->toBe('DRAFT')->and($run->checklist_snapshot['bank_reconciliation']['passed'])->toBeFalse()->and($run->checklist_snapshot['bank_reconciliation']['missing_account_ids'])->toHaveCount(1);});
it('attestasi backup dan tax review wajib bernilai true',function(){$maker=User::factory()->create(['company_id'=>1]);$run=app(PeriodCloseService::class)->prepare(1,'2026-08',['backup_verified'=>false,'tax_reviewed'=>false],$maker);expect($run->status)->toBe('DRAFT')->and($run->checklist_snapshot['backup_verified']['passed'])->toBeFalse()->and($run->checklist_snapshot['tax_reviewed']['passed'])->toBeFalse();});
